sql_query:
SELECT COUNT(VAR_id) 
FROM varInfo_synthetic 
WHERE ID = 'NEK1';

SELECT *
FROM varInfo_synthetic
WHERE ID = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT *
FROM varInfo_synthetic
WHERE ID = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT COUNT(VAR_id)
FROM varInfo_synthetic
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE ID = 'TARDBP' AND FILTER = 'PASS' AND SIFT = '-1';

SELECT *
FROM varInfo_synthetic
WHERE HighImpact = 'True' AND (ALS_1 = 'homozygous' OR ALS_2 = 'homozygous' OR ALS_3 = 'homozygous' OR ALS_4 = 'homozygous' OR ALS_5 = 'homozygous');

SELECT VAR_id, ID, REF, ALT, AF 
FROM varInfo_synthetic 
ORDER BY AC DESC;

SELECT COUNT(VAR_id) 
FROM varInfo_synthetic 
WHERE ALS_1 = '1' AND HighImpact = '1';

SELECT VAR_id, gene_name, HighImpact, ModerateImpact 
FROM varInfo_synthetic 
WHERE (HighImpact = 'YES' OR ModerateImpact = 'YES') AND (ALS_1 = 'NO' OR ALS_2 = 'NO' OR ALS_3 = 'NO' OR ALS_4 = 'NO' OR ALS_5 = 'NO');

SELECT *
FROM varInfo_synthetic
WHERE Synonymous = 'True' AND HighImpact = 'True';

SELECT ALS_2 AS Female_Carriers 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND FILTER = 'PASS' AND Control_4 = 0;
